/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-video .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-video .sl-btn-primary { background-color: var(--smartlearn-btn-bg) !important; border-color: var(--smartlearn-btn-bg) !important; color: var(--smartlearn-btn-text, #ffffff) !important; }
.sl-hero-video .sl-btn-primary:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important; filter: brightness(0.9); }
.sl-hero-video .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-video .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-video {
    min-height: 85vh;
}
.sl-hero-video .object-fit-cover {
    object-fit: cover;
}
.sl-hero-video .text-shadow {
    text-shadow: 0 4px 20px rgba(0,0,0,0.4);
}
.sl-hero-video .font-light {
    font-weight: 300;
}
.sl-hero-video .sl-cinematic-title {
    line-height: 1.1;
    letter-spacing: -0.02em;
}
.sl-hero-video .glass-rating-card {
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
    max-width: 320px;
    transition: transform 0.3s ease;
}
.sl-hero-video .glass-rating-card:hover {
    transform: translateY(-5px);
}
.sl-hero-video .sl-float-anim {
    animation: slFloat 6s ease-in-out infinite;
}
@keyframes slFloat {
    0% { transform: translateY(0px); }
    50% { transform: translateY(-15px); }
    100% { transform: translateY(0px); }
}

